import { describe, expect, it } from 'vitest';
import {
  PYTHON_UNIDATA_VERSION,
  decodeBase64Fragment,
  decodeUtf8,
  detectPii,
  quarantinePayload,
  redactValue,
  sanitizeInput,
  unquote,
} from '../src/index';
import { PY_DIGIT, PY_SPACE, PY_WORD, ignoreCase, pySub } from '../src/pyre';
import { DIGIT_RANGES, SPACE_RANGES, WORD_RANGES, type CodePointRange } from '../src/python-unicode';
import fixtureJson from './fixtures/pii-parity.json';

// Generated by services/langgraph/tests/test_pii_parity_fixture.py (Python is the reference).
interface Fixture {
  readonly protocol: string;
  readonly unidata_version: string;
  readonly detect: ReadonlyArray<{ readonly text: string; readonly expected: boolean }>;
  readonly redact: ReadonlyArray<{ readonly input: unknown; readonly output: unknown }>;
  readonly quarantine: ReadonlyArray<{ readonly input: Record<string, unknown>; readonly output: unknown }>;
  readonly sanitize: ReadonlyArray<{ readonly input: Record<string, unknown>; readonly output: unknown }>;
  readonly unquote: ReadonlyArray<{ readonly text: string; readonly output: string }>;
  readonly base64: ReadonlyArray<{ readonly fragment: string; readonly ok: boolean; readonly hex?: string }>;
  readonly utf8: ReadonlyArray<{ readonly hex: string; readonly replace: string; readonly ignore: string }>;
  readonly lower_to_ascii: readonly number[];
}

// The fixture stores long strings as {"$s": [chunks]} so no credential-shaped run
// appears contiguously in the committed file (see the Python owner).
function unchunk(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(unchunk);
  if (node === null || typeof node !== 'object') return node;
  const entries = Object.entries(node);
  const [only] = entries;
  if (entries.length === 1 && only && only[0] === '$s' && Array.isArray(only[1])) {
    return only[1].join('');
  }
  return Object.fromEntries(entries.map(([k, v]) => [k, unchunk(v)]));
}

const fixture = unchunk(fixtureJson) as Fixture;

function fromHex(hex: string): Uint8Array {
  return Uint8Array.from(hex.match(/../g) ?? [], (pair) => parseInt(pair, 16));
}

function toHex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

function allCodePoints(): number[] {
  const out: number[] = [];
  for (let cp = 0; cp < 0x110000; cp += 1) if (cp < 0xd800 || cp > 0xdfff) out.push(cp);
  return out;
}

function expand(ranges: readonly CodePointRange[]): number[] {
  return ranges.flatMap(([lo, hi]) => Array.from({ length: hi - lo + 1 }, (_, i) => lo + i));
}

describe('@amc/pii parity with the Python reference', () => {
  it('uses the fixture protocol and Python Unicode tables', () => {
    expect(fixture.protocol).toBe('AMC-PII-PARITY-1');
    expect(PYTHON_UNIDATA_VERSION).toBe(fixture.unidata_version);
    expect(fixture.detect.filter((c) => c.expected).length).toBeGreaterThan(100);
    expect(fixture.detect.filter((c) => !c.expected).length).toBeGreaterThan(100);
  });

  it('detects exactly what Python detects', () => {
    for (const c of fixture.detect) expect(detectPii(c.text), JSON.stringify(c.text)).toBe(c.expected);
  });

  it('redacts exactly like Python', () => {
    for (const c of fixture.redact) expect(redactValue(c.input), JSON.stringify(c.input)).toStrictEqual(c.output);
    for (const c of fixture.quarantine) expect(quarantinePayload(c.input)).toStrictEqual(c.output);
  });

  it('sanitizes exactly like Python', () => {
    for (const c of fixture.sanitize) expect(sanitizeInput(c.input), JSON.stringify(c.input)).toStrictEqual(c.output);
  });

  it('reproduces urllib.parse.unquote', () => {
    for (const c of fixture.unquote) expect(unquote(c.text), JSON.stringify(c.text)).toBe(c.output);
  });

  it('reproduces base64.b64decode(validate=True) on scanner fragments', () => {
    for (const c of fixture.base64) {
      const result = decodeBase64Fragment(c.fragment);
      expect(result.ok, c.fragment).toBe(c.ok);
      if (result.ok) expect(toHex(result.bytes), c.fragment).toBe(c.hex);
    }
  });

  it("reproduces bytes.decode('utf-8', 'replace' | 'ignore')", () => {
    for (const c of fixture.utf8) {
      expect(decodeUtf8(fromHex(c.hex), 'replace'), c.hex).toBe(c.replace);
      expect(decodeUtf8(fromHex(c.hex), 'ignore'), c.hex).toBe(c.ignore);
    }
  });

  it('lowercases exactly the same non-ASCII code points to ASCII as Python (sensitive-key check)', () => {
    const js = allCodePoints().filter((cp) => cp > 0x7f && /^[\x00-\x7f]+$/.test(String.fromCodePoint(cp).toLowerCase()));
    expect(js).toStrictEqual(fixture.lower_to_ascii);
  });
});

describe('@amc/pii regex building blocks', () => {
  it('compiles the Python \\w, \\d and \\s tables into classes that match exactly those code points', () => {
    const all = String.fromCodePoint(...allCodePoints().filter((cp) => cp < 0xd800));
    const astral = allCodePoints().filter((cp) => cp > 0xdfff);
    const text = all + astral.map((cp) => String.fromCodePoint(cp)).join('');
    for (const [cls, ranges] of [[PY_WORD, WORD_RANGES], [PY_DIGIT, DIGIT_RANGES], [PY_SPACE, SPACE_RANGES]] as const) {
      const hits = Array.from(text.matchAll(new RegExp(cls, 'gu')), (m) => m[0].codePointAt(0) ?? -1);
      expect(hits).toStrictEqual(expand(ranges));
    }
  });

  it('refuses inputs outside the translated shapes instead of guessing', () => {
    expect(() => ignoreCase('a-b')).toThrow();
    expect(() => decodeBase64Fragment('ab=c')).toThrow();
    expect(pySub(/x/gu, '$&$1', 'axb')).toBe('a$&$1b');
  });

  it('keeps Map payloads redacted instead of passing them through', () => {
    const redacted = redactValue(new Map<string, unknown>([['Password', 'p'], ['note', 'ada@example.test']]));
    expect(redacted).toStrictEqual(new Map([['Password', '[REDACTED_SENSITIVE_FIELD]'], ['note', '[REDACTED_EMAIL]']]));
  });
});
